 */
class Show {

    private final int  MAX_TIMES = 100;
    public int[]       times = new int[MAX_TIMES];
    public int         timeIndex;
    public int         priority;
    public String      title;
    
    
    public Show()
    {
        title = new String("\0");
        priority = -1;
        timeIndex = 0;
        for(int index = 0; index < 100; index++)
